public record TargetPolicy(List<String> includeAll, List<String> excludeAny, List<String> includeAny) {

    /**
     * 由原始请求列表构建并校验策略：
     * 空条件（已给出但为空列表）与全空策略 422；标签重复 422；同标签同时要求包含与排除 422。
