    @Test
    void 批量修改_重复设备_空变更_增删交集_重复标签_均422() throws Exception {
        registerDevice("r1", "d1", "m1", 1, "[\"a\"]");

        MvcResult dupDevice = batchUpdate("c1", "op1", """
                [{"deviceId":"d1","add":["x"]},{"deviceId":"d1","add":["y"]}]
                """);
