                [{"deviceId":"d1"}]
                """);
        assertThat(emptyChange.getResponse().getStatus()).isEqualTo(422);
        assertThat(emptyChange.getResponse().getContentAsString()).contains("EMPTY_TAG_CHANGE");

        MvcResult addRemove = batchUpdate("c3", "op1", """
